//! Index construction: trigram posting lists (FR-4) and JSON (de)serialization (FR-5).

use crate::{Doc, Index, Result};
use std::collections::{BTreeMap, BTreeSet};

/// Every window of 3 consecutive chars of `text`, case-folded (FR-4).
/// `"Limits"` → `["lim", "imi", "mit", "its"]` — the blog's example.
/// Shared by indexing and query expansion so both sides tokenize identically.
pub fn trigrams(text: &str) -> Vec<String> {
    // [ITERATORS] Chained lazy adapters, like C# LINQ or Python generator
    // pipelines — but compiled to a plain loop with zero allocation until
    // `collect()`. `windows(3)` borrows overlapping slices instead of
    // copying, something Python's slicing can't express.
    let chars: Vec<char> = text.to_lowercase().chars().collect();
    chars.windows(3).map(|w| w.iter().collect()).collect()
}

/// Build the inverted index from deduplicated docs (FR-4, FR-5).
pub fn build(source: String, docs: Vec<Doc>) -> Index {
    let mut grams: BTreeMap<String, Vec<u32>> = BTreeMap::new();
    for doc in &docs {
        // A set per doc: a gram appearing 50 times in one file still posts
        // one doc ID. Doc IDs ascend, so pushing keeps posting lists sorted —
        // which is what makes merge-intersection (FR-7) possible later.
        let distinct: BTreeSet<String> = trigrams(&doc.content).into_iter().collect();
        for gram in distinct {
            grams.entry(gram).or_default().push(doc.id);
        }
    }
    Index {
        version: 1,
        source,
        docs,
        grams,
    }
}

/// Write the index as JSON (FR-5).
pub fn save(index: &Index, path: &str) -> Result<()> {
    // [TRAITS] `serde_json::to_string` works on *any* type implementing
    // `Serialize` — ad-hoc polymorphism via traits, resolved at compile
    // time. Python's json module inspects objects at runtime; C# reflection
    // does too (unless source-generated). Here the code is generated by
    // the derive in lib.rs, so a typo'd field is a compile error.
    std::fs::write(path, serde_json::to_string(index)?)?;
    Ok(())
}

/// Read an index back from JSON.
pub fn load(path: &str) -> Result<Index> {
    Ok(serde_json::from_str(&std::fs::read_to_string(path)?)?)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn doc(id: u32, content: &str) -> Doc {
        Doc {
            id,
            paths: vec![format!("f{id}.txt")],
            hash: String::new(),
            content: content.to_string(),
        }
    }

    #[test]
    fn trigrams_match_blog_example() {
        assert_eq!(trigrams("limits"), ["lim", "imi", "mit", "its"]);
        assert_eq!(trigrams("Limits"), trigrams("limits"), "case-folded");
        assert!(trigrams("ab").is_empty(), "too short for a trigram");
    }

    #[test]
    fn posting_lists_are_sorted_and_deduped() {
        let idx = build("test".into(), vec![doc(0, "aaaa aaaa"), doc(1, "aaaa")]);
        assert_eq!(idx.grams["aaa"], vec![0, 1]);
    }

    #[test]
    fn roundtrips_through_json() {
        let idx = build("test".into(), vec![doc(0, "hello world")]);
        let path = std::env::temp_dir().join("mini-bb-roundtrip.json");
        let path = path.to_str().unwrap();
        save(&idx, path).unwrap();
        let loaded = load(path).unwrap();
        assert_eq!(loaded.grams, idx.grams);
        assert_eq!(loaded.docs[0].content, "hello world");
        let _ = std::fs::remove_file(path);
    }
}

//! Plan execution: posting-list intersection/union (FR-7), verification
//! (FR-8), and match snippets (FR-9).

use crate::query::{TermPlan, Variant};
use crate::{Doc, Index};

/// A verified match: the doc plus, per term, the first matching line.
pub struct Match<'a> {
    // [LIFETIMES] `'a` says: this Match *borrows* from an Index that must
    // outlive it. Python/C# would let results outlive (and pin) the index
    // via GC; Rust instead proves at compile time that we never hold a
    // result after the index is gone — no copy of the doc is ever made.
    pub doc: &'a Doc,
    /// (matched variant literal, 1-based line number, line text) per term.
    pub lines: Vec<(String, usize, String)>,
}

/// Execute the FR-7 plan: AND over terms ( OR over variants ( AND over the
/// variant's posting lists ) ) → candidate doc IDs. Trigram hits are
/// necessary but not sufficient: a doc holding `abc` and `bcd` need not
/// contain `abcd`. Verification (below) fixes that.
pub fn candidates(index: &Index, plans: &[TermPlan]) -> Vec<u32> {
    let mut acc: Option<Vec<u32>> = None;
    for p in plans {
        let ids = term_candidates(index, &p.variants);
        // [ENUMS+MATCH] `Option` instead of a magic "not started" sentinel:
        // `None` = no term processed yet, `Some(ids)` = running intersection.
        // Python would use `acc = None` too — but nothing there *forces* the
        // None-check; here forgetting it simply doesn't compile.
        acc = Some(match acc {
            None => ids,
            Some(prev) => intersect(&prev, &ids),
        });
    }
    acc.unwrap_or_default()
}

/// OR across one term's variants: union of each variant's gram intersection.
/// A sub-trigram variant (scan_all) can't be gated, so the whole term
/// degenerates to "all docs" and verification does the real work.
fn term_candidates(index: &Index, variants: &[Variant]) -> Vec<u32> {
    let mut ids: Vec<u32> = Vec::new();
    for v in variants {
        if v.scan_all {
            return index.docs.iter().map(|d| d.id).collect();
        }
        let mut lists: Vec<&[u32]> = v
            .grams
            .iter()
            .map(|g| index.grams.get(g).map_or(&[][..], |l| l))
            .collect();
        // Smallest list first: the intersection can only shrink, so starting
        // tiny keeps every later merge cheap (Blackbird's lazy iterators
        // exploit the same idea).
        lists.sort_by_key(|l| l.len());
        let mut v_ids: Vec<u32> = lists[0].to_vec();
        for l in &lists[1..] {
            v_ids = intersect(&v_ids, l);
            if v_ids.is_empty() {
                break;
            }
        }
        ids = union(&ids, &v_ids);
    }
    ids
}

/// Classic two-pointer merge of sorted ID lists — the reason posting lists
/// are kept sorted (FR-4). O(n+m), no hashing, no allocation per element.
fn intersect(a: &[u32], b: &[u32]) -> Vec<u32> {
    let (mut i, mut j, mut out) = (0, 0, Vec::new());
    while i < a.len() && j < b.len() {
        // [ENUMS+MATCH] Three-way compare returns the `Ordering` enum and
        // `match` must handle all variants — the compiler rejects a missing
        // `Equal` arm, unlike an if/elif chain that silently falls through.
        match a[i].cmp(&b[j]) {
            std::cmp::Ordering::Less => i += 1,
            std::cmp::Ordering::Greater => j += 1,
            std::cmp::Ordering::Equal => {
                out.push(a[i]);
                i += 1;
                j += 1;
            }
        }
    }
    out
}

/// The same merge walk as `intersect`, keeping everything once (sorted OR).
fn union(a: &[u32], b: &[u32]) -> Vec<u32> {
    let (mut i, mut j, mut out) = (0, 0, Vec::new());
    while i < a.len() && j < b.len() {
        match a[i].cmp(&b[j]) {
            std::cmp::Ordering::Less => {
                out.push(a[i]);
                i += 1;
            }
            std::cmp::Ordering::Greater => {
                out.push(b[j]);
                j += 1;
            }
            std::cmp::Ordering::Equal => {
                out.push(a[i]);
                i += 1;
                j += 1;
            }
        }
    }
    // One side is exhausted; the sorted remainder of the other passes through.
    out.extend_from_slice(&a[i..]);
    out.extend_from_slice(&b[j..]);
    out
}

/// Verify candidates against real content (FR-8) and collect snippets (FR-9):
/// a doc matches when every term has at least one variant literal present.
/// Case-insensitive by construction: literals are already folded, content is
/// folded here — like Blackbird, correctness comes from this pass, not the index.
pub fn verify<'a>(index: &'a Index, plans: &[TermPlan], ids: &[u32]) -> Vec<Match<'a>> {
    let mut out = Vec::new();
    for &id in ids {
        let doc = &index.docs[id as usize];
        let folded = doc.content.to_lowercase();
        let hit = |p: &TermPlan| p.variants.iter().any(|v| folded.contains(&v.literal));
        if !plans.iter().all(hit) {
            continue;
        }
        let lines = plans
            .iter()
            .filter_map(|p| {
                // [ITERATORS] `find_map` is lazy: it walks lines until the
                // first one containing any variant, like C#'s LINQ `First` —
                // not Python's typical "build the whole list, take [0]".
                folded.lines().enumerate().find_map(|(n, l)| {
                    let v = p.variants.iter().find(|v| l.contains(&v.literal))?;
                    let text = doc.content.lines().nth(n).unwrap_or("").to_string();
                    Some((v.literal.clone(), n + 1, text))
                })
            })
            .collect();
        out.push(Match { doc, lines });
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::index::build;
    use crate::query::{parse, plan};

    fn idx(contents: &[&str]) -> Index {
        let docs = contents
            .iter()
            .enumerate()
            .map(|(i, c)| Doc {
                id: i as u32,
                paths: vec![format!("f{i}.txt")],
                hash: String::new(),
                content: c.to_string(),
            })
            .collect();
        build("test".into(), docs)
    }

    fn search(index: &Index, q: &str) -> Vec<u32> {
        let plans = plan(&parse(q));
        let cand = candidates(index, &plans);
        verify(index, &plans, &cand)
            .iter()
            .map(|m| m.doc.id)
            .collect()
    }

    #[test]
    fn intersect_and_union_merge_sorted_lists() {
        assert_eq!(intersect(&[1, 3, 5, 7], &[2, 3, 7, 9]), vec![3, 7]);
        assert_eq!(intersect(&[], &[1]), Vec::<u32>::new());
        assert_eq!(union(&[1, 3, 7], &[2, 3, 9]), vec![1, 2, 3, 7, 9]);
        assert_eq!(union(&[], &[1, 2]), vec![1, 2]);
    }

    #[test]
    fn verification_kills_trigram_false_positives() {
        // Doc 1 contains the trigrams `abc` and `bcd` but not "abcd":
        // it is a candidate (M2 acceptance case) and must be filtered out.
        let index = idx(&["say abcd here", "abc then bcd separately"]);
        let plans = plan(&parse("abcd"));
        assert_eq!(
            candidates(&index, &plans),
            vec![0, 1],
            "both are candidates"
        );
        assert_eq!(
            search(&index, "abcd"),
            vec![0],
            "only doc 0 survives verify"
        );
    }

    #[test]
    fn regex_subset_matches_either_variant() {
        let index = idx(&["one argument only", "many arguments here", "argue"]);
        assert_eq!(search(&index, "arguments?"), vec![0, 1]);
        assert_eq!(search(&index, "argu(e|ment)"), vec![0, 1, 2]);
    }

    #[test]
    fn multi_term_is_and_and_case_insensitive() {
        let index = idx(&["Hello World", "hello there", "world only"]);
        assert_eq!(search(&index, "hello world"), vec![0]);
        assert_eq!(search(&index, "HELLO"), vec![0, 1]);
    }

    #[test]
    fn short_terms_scan_all_docs() {
        let index = idx(&["xy here", "nothing"]);
        assert_eq!(search(&index, "xy"), vec![0]);
    }

    #[test]
    fn snippets_report_first_matching_line() {
        let index = idx(&["no hit\nfn main() {\n}"]);
        let plans = plan(&parse(r#""fn main""#));
        let m = verify(&index, &plans, &[0]);
        assert_eq!(m[0].lines[0], ("fn main".into(), 2, "fn main() {".into()));
    }
}

//! mini-bb — an educational trigram code-search engine.
//! Spec: spec/001-trigram-engine.md; architecture map: docs/architecture.md.
//!
//! Pipeline: `ingest` (clone/walk/dedupe) → `index` (trigram posting lists)
//! → `query` (parse + expand to a trigram plan) → `search` (intersect +
//! verify). Module layout and budgets are fixed by spec 001 §6.

pub mod index;
pub mod ingest;
pub mod query;
pub mod search;

// [DERIVE] `derive` asks the compiler to *generate* trait implementations at
// compile time — Rust's answer to Python decorators / C# attributes, except
// nothing happens at runtime: serde emits real (de)serialization code here.
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

// [ERRORS] Rust has no exceptions. Fallible functions return
// `Result<T, E>` (like Go, or C#'s Try* pattern made mandatory), and the
// caller *must* do something with it. `Box<dyn Error>` is a trait object —
// "any error type" — the closest thing to `catch (Exception e)`.
pub type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

/// One deduplicated document (Blackbird shards by git blob SHA; we dedupe by
/// content hash — identical files across paths are indexed once, FR-3).
#[derive(Debug, Serialize, Deserialize)]
pub struct Doc {
    pub id: u32,
    /// All paths whose content hashed identically.
    pub paths: Vec<String>,
    pub hash: String,
    pub content: String,
}

/// The whole searchable index — serialized to a single JSON file (FR-5).
#[derive(Debug, Serialize, Deserialize)]
pub struct Index {
    pub version: u32,
    pub source: String,
    pub docs: Vec<Doc>,
    /// trigram → sorted, deduplicated doc IDs (the posting lists, FR-4).
    // [TRAITS] BTreeMap (not HashMap) so JSON output is deterministic: its
    // keys only need `Ord`. Python dicts keep insertion order; Rust's
    // HashMap order is deliberately randomized, so determinism is opt-in
    // via a different data structure rather than a dict flag.
    pub grams: BTreeMap<String, Vec<u32>>,
}

/// FNV-1a 64-bit content hash (FR-3). Six lines beats a dependency, and —
/// unlike Python's `hash()` or C#'s `GetHashCode()` — it is stable across
/// runs, which an on-disk index requires.
pub fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in bytes {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
        // [OWNERSHIP] `wrapping_mul`: integer overflow is a *panic* in debug
        // builds, not silent wraparound like C#'s unchecked math or a
        // silent bigint promotion like Python. Hashing wants wraparound,
        // so we must say so explicitly.
    }
    h
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fnv_is_stable_across_runs() {
        // Known FNV-1a test vector: empty input returns the offset basis.
        assert_eq!(fnv1a(b""), 0xcbf2_9ce4_8422_2325);
        assert_eq!(fnv1a(b"hello"), fnv1a(b"hello"));
        assert_ne!(fnv1a(b"hello"), fnv1a(b"world"));
    }
}

//! CLI entry point: `mini-bb index` (FR-1..FR-5) and `mini-bb search`
//! (FR-6..FR-9). Output formatting lives here so the engine stays pure.

use clap::Parser;

// [DERIVE] clap builds the whole argument parser from this type at compile
// time — compare Python's argparse (imperative, runtime) or C#'s
// System.CommandLine (builder pattern). The enum *is* the CLI contract:
// `--help`, validation, and typed values all fall out of the definition.
#[derive(Parser)]
#[command(about = "Educational trigram code search (mini Blackbird) — see spec/")]
enum Cmd {
    /// Index a public GitHub repo URL or local directory into a JSON file.
    Index {
        /// GitHub URL (https://github.com/owner/repo) or local path.
        source: String,
        /// Where to write the index.
        #[arg(short, long, default_value = "index.json")]
        output: String,
    },
    /// Search an index, showing the trigram plan the query expands into.
    Search {
        /// Bare words and "quoted strings", ANDed together (case-insensitive).
        query: String,
        /// Index file produced by `index`.
        #[arg(short, long, default_value = "index.json")]
        index: String,
        /// Stop after showing the plan and candidates; skip verification.
        #[arg(long)]
        explain: bool,
    },
}

fn main() {
    // [ERRORS] main delegates to a Result-returning function and maps any
    // error to a one-line message + non-zero exit (NF-5). This is the Rust
    // idiom for "top-level exception handler": errors bubble via `?`, and
    // only the outermost layer decides how to present them.
    if let Err(e) = run(Cmd::parse()) {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

fn run(cmd: Cmd) -> mini_bb::Result<()> {
    match cmd {
        Cmd::Index { source, output } => cmd_index(source, &output),
        Cmd::Search {
            query,
            index,
            explain,
        } => cmd_search(&query, &index, explain),
    }
}

fn cmd_index(source: String, output: &str) -> mini_bb::Result<()> {
    let (docs, stats) = mini_bb::ingest::ingest(&source)?;
    let idx = mini_bb::index::build(source, docs);
    mini_bb::index::save(&idx, output)?;
    let bytes = std::fs::metadata(output)?.len();
    println!(
        "indexed {} docs ({} duplicate paths merged, {} files skipped)",
        stats.indexed, stats.merged, stats.skipped
    );
    println!(
        "{} distinct trigrams → {} ({} KB)",
        idx.grams.len(),
        output,
        bytes / 1024
    );
    Ok(())
}

/// ANSI-bold the (already-lowercased) term inside an original-case line.
/// We search the folded copy but splice the original by byte offset, so
/// `Config` highlights when the term is `config`. If case folding changed
/// byte lengths (rare Unicode edge), skip highlighting rather than panic.
fn highlight(text: &str, term: &str) -> String {
    let folded = text.to_lowercase();
    let end = |i: usize| i + term.len();
    match folded.find(term) {
        // [BORROWING] `&text[..i]` slices borrow the original string —
        // three views, zero copies until `format!` assembles the result.
        // Python slices copy; C# needs Span<char> to get this for free.
        Some(i)
            if folded.len() == text.len()
                && text.is_char_boundary(i)
                && text.is_char_boundary(end(i)) =>
        {
            format!(
                "{}\x1b[1m{}\x1b[0m{}",
                &text[..i],
                &text[i..end(i)],
                &text[end(i)..]
            )
        }
        _ => text.to_string(),
    }
}

/// The FR-9 pipeline display: terms → expansion → plan → candidates → matches.
fn cmd_search(query: &str, index_path: &str, explain: bool) -> mini_bb::Result<()> {
    let idx = mini_bb::index::load(index_path)?;
    let terms = mini_bb::query::parse(query);
    if terms.is_empty() {
        return Err("empty query".into());
    }
    let shown: Vec<&str> = terms.iter().map(|t| t.raw.as_str()).collect();
    println!("1. terms (AND):      {shown:?}");
    let plans = mini_bb::query::plan(&terms);
    for p in &plans {
        let vars: Vec<&str> = p.variants.iter().map(|v| v.literal.as_str()).collect();
        println!("2. expand {:12} → {}", p.term, vars.join(" ∨ "));
    }
    for p in &plans {
        let sides: Vec<String> = p
            .variants
            .iter()
            .map(|v| {
                if v.scan_all {
                    format!("{:?} shorter than a trigram: full scan!", v.literal)
                } else {
                    let sized: Vec<String> = v
                        .grams
                        .iter()
                        .map(|g| format!("{g}[{}]", idx.grams.get(g).map_or(0, Vec::len)))
                        .collect();
                    format!("({})", sized.join(" ∧ "))
                }
            })
            .collect();
        println!(
            "3. plan for {:9} → {} — [n] = posting-list length",
            p.term,
            sides.join(" ∨ ")
        );
    }
    let cand = mini_bb::search::candidates(&idx, &plans);
    println!(
        "4. candidates after intersection: {} of {} docs",
        cand.len(),
        idx.docs.len()
    );
    if explain {
        return Ok(());
    }
    let matches = mini_bb::search::verify(&idx, &plans, &cand);
    println!(
        "5. verified matches: {} (false positives removed: {})",
        matches.len(),
        cand.len() - matches.len()
    );
    for m in &matches {
        println!("\n  {}", m.doc.paths.join("  =  "));
        for (term, line_no, text) in &m.lines {
            println!("    {line_no}: {}", highlight(text.trim_end(), term));
        }
    }
    Ok(())
}

//! Ingestion: fetch a repo (FR-1), filter files (FR-2), dedupe (FR-3).

use crate::{fnv1a, Doc, Result};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Files larger than this are skipped (FR-2).
const MAX_FILE_BYTES: u64 = 200 * 1024;

/// Counters reported to the user instead of failing the run (FR-2, FR-3).
#[derive(Debug, Default)]
pub struct Stats {
    pub indexed: usize,
    pub merged: usize,
    pub skipped: usize,
}

/// Ingest a source (GitHub URL or local directory) into deduplicated docs.
pub fn ingest(source: &str) -> Result<(Vec<Doc>, Stats)> {
    // [ENUMS+MATCH] No `if isinstance(...)` chain: we branch on data and the
    // temp dir is an `Option<PathBuf>` — the "maybe a value" case is a real
    // type, not a nullable reference (C#) or an implicit None (Python).
    let (root, tmp) = if source.starts_with("http://") || source.starts_with("https://") {
        let dir = clone_shallow(source)?;
        (dir.clone(), Some(dir))
    } else {
        (PathBuf::from(source), None)
    };

    let mut docs: Vec<Doc> = Vec::new();
    let mut by_hash: HashMap<u64, usize> = HashMap::new();
    let mut stats = Stats::default();
    walk(&root, &root, &mut docs, &mut by_hash, &mut stats)?;

    // Best-effort cleanup of the clone; a leftover temp dir is not an error.
    if let Some(dir) = tmp {
        let _ = std::fs::remove_dir_all(dir);
    }
    Ok((docs, stats))
}

/// `git clone --depth 1` into a temp dir (FR-1). Shelling out to git keeps
/// us dependency-free and mirrors how you'd do this in a Python subprocess.
fn clone_shallow(url: &str) -> Result<PathBuf> {
    let dir = std::env::temp_dir().join(format!("mini-bb-{}", std::process::id()));
    // [ERRORS] The `?` operator: "return the error to my caller if this
    // failed, otherwise unwrap the value". It replaces try/except and
    // try/catch blocks with one character, but the propagation is *visible*
    // at every call site — no invisible exception control flow.
    let out = Command::new("git")
        .args(["clone", "--depth", "1", url])
        .arg(&dir)
        .output()?;
    if !out.status.success() {
        return Err(format!("git clone failed: {}", String::from_utf8_lossy(&out.stderr)).into());
    }
    Ok(dir)
}

/// Recursive directory walk collecting deduplicated text files.
fn walk(
    root: &Path,
    dir: &Path,
    docs: &mut Vec<Doc>,
    by_hash: &mut HashMap<u64, usize>,
    stats: &mut Stats,
) -> Result<()> {
    // [BORROWING] `docs`, `by_hash` and `stats` are `&mut` — explicit,
    // exclusive, temporary loans. In Python/C# any callee holding the object
    // reference could mutate it at any time; here mutation rights are part
    // of the function signature and enforced by the compiler.
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let name = entry.file_name();
        if path.is_dir() {
            // FR-2: skip git internals, dot-dirs, and build output.
            let name = name.to_string_lossy();
            if name.starts_with('.') || name == "target" || name == "node_modules" {
                continue;
            }
            walk(root, &path, docs, by_hash, stats)?;
            continue;
        }
        if entry.metadata()?.len() > MAX_FILE_BYTES {
            stats.skipped += 1;
            continue;
        }
        // [ENUMS+MATCH] UTF-8 validation returns Result, and `match` must
        // handle both arms — you cannot forget the "binary file" case the
        // way an unhandled UnicodeDecodeError slips through in Python.
        let content = match String::from_utf8(std::fs::read(&path)?) {
            Ok(text) => text,
            Err(_) => {
                stats.skipped += 1;
                continue;
            }
        };
        let rel = path
            .strip_prefix(root)
            .unwrap_or(&path)
            .to_string_lossy()
            .into_owned();
        add_doc(docs, by_hash, stats, rel, content);
    }
    Ok(())
}

/// Content-addressed insert (FR-3): identical content merges into one doc.
fn add_doc(
    docs: &mut Vec<Doc>,
    by_hash: &mut HashMap<u64, usize>,
    stats: &mut Stats,
    path: String,
    content: String,
) {
    let hash = fnv1a(content.as_bytes());
    if let Some(&i) = by_hash.get(&hash) {
        docs[i].paths.push(path);
        stats.merged += 1;
        return;
    }
    by_hash.insert(hash, docs.len());
    stats.indexed += 1;
    // [OWNERSHIP] `content` is *moved* into the Doc — no copy is made and
    // the local variable is dead afterwards. Python and C# would share a
    // reference here; Rust transfers ownership so exactly one owner frees it.
    docs.push(Doc {
        id: docs.len() as u32,
        paths: vec![path],
        hash: format!("{hash:016x}"),
        content,
    });
}

