//! Query parsing and expansion into a trigram plan (FR-6).
//!
//! Blackbird compiles `/arguments?/` into `arg ∧ rgu ∧ gum ∧ (… ∨ …)`.
//! We do the same shape: each term expands into literal *variants* (OR),
//! each variant into covering trigrams (AND). Bare terms get a tiny regex
//! subset — `?` (previous char optional), `(a|b)` alternation, `\` escape —
//! while quoted terms stay fully literal.

use crate::index::trigrams;

/// One literal alternative of a term, with the trigrams that gate it.
/// A variant shorter than 3 chars has no trigram and forces a full scan
/// (FR-6) — kept explicit so the output can teach *why* that's bad.
#[derive(Debug, PartialEq)]
pub struct Variant {
    pub literal: String,
    pub grams: Vec<String>,
    pub scan_all: bool,
}

/// One term's slice of the plan: variants are ORed, terms are ANDed (FR-7).
#[derive(Debug, PartialEq)]
pub struct TermPlan {
    pub term: String,
    pub variants: Vec<Variant>,
}

/// A parsed term: raw text plus whether it was quoted (quoted = literal,
/// no regex expansion).
#[derive(Debug, PartialEq)]
pub struct Term {
    pub raw: String,
    pub quoted: bool,
}

/// Split a query into case-folded terms: bare words plus `"quoted strings"`
/// (FR-6). Unclosed quotes just run to end of input.
pub fn parse(query: &str) -> Vec<Term> {
    let mut terms = Vec::new();
    let mut cur = String::new();
    let mut in_quotes = false;
    // [ENUMS+MATCH] A hand-rolled state machine over a char iterator.
    // `match` on `(char, bool)` tuples makes every state/input pair an
    // explicit arm — Rust pushes states into values rather than Python's
    // "flag variables plus careful if-ordering".
    for c in query.chars() {
        match (c, in_quotes) {
            ('"', q) => {
                flush(&mut terms, &mut cur, q);
                in_quotes = !q;
            }
            (c, false) if c.is_whitespace() => flush(&mut terms, &mut cur, false),
            (c, _) => cur.push(c),
        }
    }
    flush(&mut terms, &mut cur, in_quotes);
    terms
}

// [BORROWING] The first two parameters are mutable borrows: this helper
// edits the caller's data in place and owns nothing. The signature alone
// tells you that — in Python/C# you'd read the body to know it mutates.
fn flush(terms: &mut Vec<Term>, cur: &mut String, quoted: bool) {
    if !cur.is_empty() {
        terms.push(Term {
            raw: cur.to_lowercase(),
            quoted,
        });
        cur.clear();
    }
}

/// Expand a bare term's regex subset into every literal variant (FR-6):
/// `arguments?` → `["argument", "arguments"]`, `(foo|bar)s` → `["foos", "bars"]`.
/// No cap on combinations — a teaching tool trusts its user's queries.
fn expand(raw: &str) -> Vec<String> {
    // Start with one empty variant and extend every variant per input char —
    // groups multiply the set, `?` doubles it (with/without the last char).
    let mut out = vec![String::new()];
    let mut chars = raw.chars();
    while let Some(c) = chars.next() {
        match c {
            '\\' => {
                if let Some(esc) = chars.next() {
                    out.iter_mut().for_each(|v| v.push(esc));
                }
            }
            '(' => {
                let group: String = chars.by_ref().take_while(|&g| g != ')').collect();
                // [ITERATORS] A cross product with no index bookkeeping:
                // for each existing variant × each branch, produce a new
                // string. `flat_map` is Python's nested comprehension /
                // C#'s SelectMany, checked for type mismatches at compile time.
                out = out
                    .iter()
                    .flat_map(|v| group.split('|').map(move |b| format!("{v}{b}")))
                    .collect();
            }
            '?' => {
                let mut without: Vec<String> = out
                    .iter()
                    .map(|v| {
                        let mut w = v.clone();
                        w.pop();
                        w
                    })
                    .collect();
                out.append(&mut without);
                out.sort();
                out.dedup();
            }
            c => out.iter_mut().for_each(|v| v.push(c)),
        }
    }
    out
}

/// Expand each term into ORed variants, each with its covering trigram set.
pub fn plan(terms: &[Term]) -> Vec<TermPlan> {
    terms
        .iter()
        .map(|t| {
            let literals = if t.quoted {
                vec![t.raw.clone()]
            } else {
                expand(&t.raw)
            };
            let variants = literals
                .into_iter()
                .map(|literal| {
                    let grams = trigrams(&literal);
                    Variant {
                        scan_all: grams.is_empty(),
                        literal,
                        grams,
                    }
                })
                .collect();
            TermPlan {
                term: t.raw.clone(),
                variants,
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn raws(q: &str) -> Vec<String> {
        parse(q).into_iter().map(|t| t.raw).collect()
    }

    #[test]
    fn parses_bare_and_quoted_terms() {
        assert_eq!(raws("foo bar"), ["foo", "bar"]);
        assert_eq!(raws(r#""fn main" Config"#), ["fn main", "config"]);
        assert_eq!(raws("  "), Vec::<String>::new());
        assert_eq!(raws(r#""unclosed quote"#), ["unclosed quote"]);
        assert!(parse(r#""a?b""#)[0].quoted);
        assert!(!parse("a?b")[0].quoted);
    }

    #[test]
    fn expands_blog_example_optional_suffix() {
        assert_eq!(expand("arguments?"), ["argument", "arguments"]);
    }

    #[test]
    fn expands_alternation_and_escapes() {
        assert_eq!(expand("(foo|bar)s"), ["foos", "bars"]);
        assert_eq!(expand(r"what\?"), ["what?"]);
        assert_eq!(expand("(a|b)(c|d)"), ["ac", "ad", "bc", "bd"]);
    }

    #[test]
    fn quoted_terms_are_not_expanded() {
        let p = plan(&parse(r#""a?b""#));
        assert_eq!(p[0].variants.len(), 1);
        assert_eq!(p[0].variants[0].literal, "a?b");
    }

    #[test]
    fn variants_carry_covering_trigrams() {
        let p = plan(&parse("limits"));
        assert_eq!(p[0].variants[0].grams, ["lim", "imi", "mit", "its"]);
        assert!(!p[0].variants[0].scan_all);
    }

    #[test]
    fn short_variants_fall_back_to_full_scan() {
        let p = plan(&parse("ab"));
        assert!(p[0].variants[0].scan_all);
        // `x?` expands to "" and "x" — both sub-trigram, both full scan.
        let p = plan(&parse("x?"));
        assert!(p[0].variants.iter().all(|v| v.scan_all));
    }
}

//! Distributed mini-bb (spec 003): the Blackbird pipeline in miniature.
//!
//! Ingest is ASYNC via real Kafka messages: a push event on the `pushes`
//! topic wakes the crawler, which produces one document message per file to
//! the `docs` topic, partitioned by content hash — and each of the three
//! shards consumes exactly one partition, building its own spec-001 index.
//! Queries are SYNC: HTTP fan-out to every shard, results merged. That
//! ingest/query asymmetry is the whole lesson (see the spec's blog quotes).

use mini_bb::{fnv1a, index, ingest, query, search, Doc, Index};
use rskafka::client::partition::{Compression, PartitionClient, UnknownTopicHandling};
use rskafka::client::{Client, ClientBuilder};
use rskafka::record::Record;
use serde_json::{json, Value};
use std::sync::{Arc, Mutex};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{broadcast, RwLock};

const SHARDS: usize = 3;

// [ASYNC] Everything below runs on tokio, Rust's async runtime. Unlike
// Python's asyncio (built into the interpreter) or C#'s Task machinery
// (built into the CLR), Rust ships *no* runtime — async/await compiles to
// state machines and a library crate schedules them. `#[tokio::main]`
// installs that scheduler around main.
#[tokio::main]
async fn main() {
    if let Err(e) = run().await {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

/// Every pipeline step is emitted as one JSON line: to SSE subscribers
/// (DEMO-5) and, with --record, to the replay file used by the web UI.
struct Emitter {
    tx: broadcast::Sender<String>,
    rec: Option<Mutex<std::fs::File>>,
}

impl Emitter {
    fn emit(&self, ev: &str, mut data: Value) {
        data["ev"] = ev.into();
        data["ts"] = chrono::Utc::now().timestamp_millis().into();
        let line = data.to_string();
        // [ERRORS] Both sends are allowed to fail silently: no SSE
        // subscriber and a full channel are normal, not bugs. The explicit
        // `let _ =` is Rust's way of saying "I considered this Result and
        // chose to drop it" — an unused Result is a compiler warning.
        let _ = self.tx.send(line.clone());
        if let Some(f) = &self.rec {
            use std::io::Write;
            if let Ok(mut f) = f.lock() {
                let _ = writeln!(f, "{line}");
            }
        }
    }
}

/// One shard = one Kafka partition = one independent spec-001 index (DEMO-3).
#[derive(Default)]
struct Shard {
    index: Option<Index>,
}

type Shards = Arc<Vec<RwLock<Shard>>>;

async fn run() -> mini_bb::Result<()> {
    let broker = std::env::var("KAFKA_BROKER").unwrap_or_else(|_| "localhost:9092".into());
    let record = std::env::args()
        .skip_while(|a| a != "--record")
        .nth(1)
        .map(std::fs::File::create)
        .transpose()?;
    let emitter = Arc::new(Emitter {
        tx: broadcast::channel(512).0,
        rec: record.map(Mutex::new),
    });

    let client = Arc::new(ClientBuilder::new(vec![broker.clone()]).build().await?);
    ensure_topic(&client, "pushes", 1).await?;
    ensure_topic(&client, "docs", SHARDS as i32).await?;
    let pushes = Arc::new(partition(&client, "pushes", 0).await?);
    let mut docs_parts = Vec::new();
    for p in 0..SHARDS {
        docs_parts.push(Arc::new(partition(&client, "docs", p as i32).await?));
    }

    let shards: Shards = Arc::new((0..SHARDS).map(|_| RwLock::new(Shard::default())).collect());

    // [OWNERSHIP] Each spawned task gets its own Arc clone — shared
    // ownership with an atomic refcount (like Python objects or C#
    // references, but opt-in and visible). The compiler rejects sharing
    // plain `&` references across tasks that may outlive this function.
    tokio::spawn(crawler(pushes.clone(), docs_parts.clone(), emitter.clone()));
    for (i, pc) in docs_parts.iter().enumerate() {
        tokio::spawn(shard_consumer(
            i,
            pc.clone(),
            shards.clone(),
            emitter.clone(),
        ));
    }

    println!("kafka-demo up: broker {broker}, http://localhost:7878 (/push /search?q= /events)");
    serve(pushes, shards, emitter).await
}

async fn ensure_topic(client: &Client, name: &str, partitions: i32) -> mini_bb::Result<()> {
    match client
        .controller_client()?
        .create_topic(name, partitions, 1, 5_000)
        .await
    {
        Ok(()) => Ok(()),
        // A pre-existing topic (previous run) is fine; anything else is not.
        Err(e) if e.to_string().contains("already exists") => Ok(()),
        Err(e) => Err(e.into()),
    }
}

async fn partition(client: &Client, topic: &str, p: i32) -> mini_bb::Result<PartitionClient> {
    Ok(client
        .partition_client(topic, p, UnknownTopicHandling::Retry)
        .await?)
}

fn record(value: Vec<u8>) -> Record {
    Record {
        key: None,
        value: Some(value),
        headers: Default::default(),
        timestamp: chrono::Utc::now(),
    }
}

/// DEMO-2: consume `pushes`, crawl the repo with the spec-001 ingester, and
/// produce every doc to the partition its *content hash* selects — the same
/// content-addressed sharding Blackbird does with git blob SHAs.
async fn crawler(
    pushes: Arc<PartitionClient>,
    docs_parts: Vec<Arc<PartitionClient>>,
    emitter: Arc<Emitter>,
) {
    let mut offset = 0;
    loop {
        // Long-poll fetch: returns early when a record arrives.
        let Ok((records, _)) = pushes.fetch_records(offset, 1..1_000_000, 5_000).await else {
            continue;
        };
        for r in records {
            offset = r.offset + 1;
            emitter.emit("push", json!({ "repo": "." }));
            // [ASYNC] File I/O is blocking; `spawn_blocking` moves it to a
            // thread pool so the async scheduler isn't stalled — the same
            // reason Python has loop.run_in_executor. The error is mapped
            // to String because `Box<dyn Error>` isn't `Send` (thread-safe
            // to move) — a constraint Python/C# never surface.
            let Ok(Ok((docs, stats))) =
                tokio::task::spawn_blocking(|| ingest::ingest(".").map_err(|e| e.to_string()))
                    .await
            else {
                continue;
            };
            emitter.emit(
                "crawl",
                json!({ "docs": stats.indexed, "merged": stats.merged }),
            );
            // Batch: one produce request per partition, not per doc —
            // amortizing broker round-trips is the whole point of Kafka
            // producers (real clients batch with linger.ms for the same
            // reason).
            let mut batches: Vec<Vec<Record>> = (0..SHARDS).map(|_| Vec::new()).collect();
            for doc in &docs {
                let part = (fnv1a(doc.content.as_bytes()) % SHARDS as u64) as usize;
                let Ok(value) = serde_json::to_vec(&doc) else {
                    continue;
                };
                batches[part].push(record(value));
                emitter.emit(
                    "produce",
                    json!({ "path": doc.paths[0], "partition": part }),
                );
            }
            for (part, batch) in batches.into_iter().enumerate() {
                if !batch.is_empty() {
                    let _ = docs_parts[part]
                        .produce(batch, Compression::NoCompression)
                        .await;
                }
            }
        }
    }
}

/// DEMO-3: shard i consumes ONLY partition i and rebuilds its own index
/// after each batch — "each shard consumes a single Kafka partition".
async fn shard_consumer(i: usize, pc: Arc<PartitionClient>, shards: Shards, emitter: Arc<Emitter>) {
    let mut offset = 0;
    loop {
        let Ok((records, _)) = pc.fetch_records(offset, 1..1_000_000, 5_000).await else {
            continue;
        };
        if records.is_empty() {
            continue;
        }
        let mut shard = shards[i].write().await;
        // Reclaim the docs from the previous index build; ids are LOCAL to
        // the shard (docs[id].id == id must hold within each shard's index).
        let mut docs = shard.index.take().map(|ix| ix.docs).unwrap_or_default();
        for r in records {
            offset = r.offset + 1;
            let Some(value) = r.record.value else {
                continue;
            };
            let Ok(mut doc) = serde_json::from_slice::<Doc>(&value) else {
                continue;
            };
            // Re-pushes re-produce every doc; content addressing makes the
            // dedupe trivial (ingest's FR-3 trick again, at shard level).
            if docs.iter().any(|d| d.hash == doc.hash) {
                continue;
            }
            doc.id = docs.len() as u32;
            docs.push(doc);
        }
        let ix = index::build(format!("shard-{i}"), docs);
        emitter.emit(
            "indexed",
            json!({ "shard": i, "docs": ix.docs.len(), "grams": ix.grams.len() }),
        );
        shard.index = Some(ix);
    }
}

/// DEMO-4: queries do NOT go through Kafka. Parse+plan once, fan out to all
/// shards, merge — the synchronous half of Blackbird's architecture.
async fn fan_out(q: &str, shards: &Shards, emitter: &Emitter) -> Value {
    let plans = query::plan(&query::parse(q));
    emitter.emit("fanout", json!({ "q": q, "shards": SHARDS }));
    let mut merged = Vec::new();
    let mut per_shard = Vec::new();
    for (i, sh) in shards.iter().enumerate() {
        let guard = sh.read().await;
        let mut paths: Vec<String> = guard
            .index
            .as_ref()
            .map(|ix| {
                let cand = search::candidates(ix, &plans);
                search::verify(ix, &plans, &cand)
                    .iter()
                    .flat_map(|m| m.doc.paths.iter().cloned())
                    .collect()
            })
            .unwrap_or_default();
        paths.sort();
        emitter.emit(
            "shard_result",
            json!({ "shard": i, "matches": paths.len() }),
        );
        per_shard.push(json!({ "shard": i, "paths": paths.clone() }));
        merged.extend(paths);
    }
    merged.sort();
    emitter.emit("merged", json!({ "q": q, "total": merged.len() }));
    json!({ "q": q, "shards": per_shard, "merged": merged })
}

/// DEMO-6: the tiny HTTP surface — /push, /search?q=, /events (SSE).
async fn serve(
    pushes: Arc<PartitionClient>,
    shards: Shards,
    emitter: Arc<Emitter>,
) -> mini_bb::Result<()> {
    let listener = TcpListener::bind("0.0.0.0:7878").await?;
    loop {
        let (stream, _) = listener.accept().await?;
        tokio::spawn(handle(
            stream,
            pushes.clone(),
            shards.clone(),
            emitter.clone(),
        ));
    }
}

async fn handle(
    mut s: TcpStream,
    pushes: Arc<PartitionClient>,
    shards: Shards,
    emitter: Arc<Emitter>,
) {
    let mut buf = [0u8; 2048];
    let Ok(n) = s.read(&mut buf).await else {
        return;
    };
    let head = String::from_utf8_lossy(&buf[..n]);
    let target = head.split_whitespace().nth(1).unwrap_or("/").to_string();
    const OK: &str = "HTTP/1.1 200 OK\r\nAccess-Control-Allow-Origin: *\r\n";
    if target == "/events" {
        let hdr = format!("{OK}Content-Type: text/event-stream\r\nCache-Control: no-cache\r\n\r\n");
        if s.write_all(hdr.as_bytes()).await.is_err() {
            return;
        }
        let mut rx = emitter.tx.subscribe();
        // [ENUMS+MATCH] recv() yields Result; Lagged (slow consumer) is a
        // recoverable variant we skip past, Closed ends the stream. The
        // enum forces the "what if I'm too slow?" question at compile time.
        loop {
            match rx.recv().await {
                Ok(msg) => {
                    if s.write_all(format!("data: {msg}\n\n").as_bytes())
                        .await
                        .is_err()
                    {
                        return;
                    }
                }
                Err(broadcast::error::RecvError::Lagged(_)) => continue,
                Err(broadcast::error::RecvError::Closed) => return,
            }
        }
    }
    let body = if target == "/push" {
        match pushes
            .produce(vec![record(b"push".to_vec())], Compression::NoCompression)
            .await
        {
            Ok(_) => json!({ "ok": true }).to_string(),
            Err(e) => json!({ "ok": false, "error": e.to_string() }).to_string(),
        }
    } else if let Some(qs) = target.strip_prefix("/search?q=") {
        fan_out(&percent_decode(qs), &shards, &emitter)
            .await
            .to_string()
    } else {
        let _ = s
            .write_all(b"HTTP/1.1 404 Not Found\r\nAccess-Control-Allow-Origin: *\r\n\r\n")
            .await;
        return;
    };
    let resp = format!(
        "{OK}Content-Type: application/json\r\nContent-Length: {}\r\n\r\n{body}",
        body.len()
    );
    let _ = s.write_all(resp.as_bytes()).await;
}

/// Minimal URL decoding: `+` → space, `%XX` → byte. Enough for query text.
fn percent_decode(s: &str) -> String {
    let mut out = Vec::new();
    let mut bytes = s.bytes();
    while let Some(b) = bytes.next() {
        match b {
            b'+' => out.push(b' '),
            b'%' => {
                let hi = bytes.next().unwrap_or(b'0');
                let lo = bytes.next().unwrap_or(b'0');
                let hex = [hi, lo];
                let hex = std::str::from_utf8(&hex).unwrap_or("30");
                out.push(u8::from_str_radix(hex, 16).unwrap_or(b'?'));
            }
            b => out.push(b),
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn percent_decoding() {
        assert_eq!(percent_decode("fn+main"), "fn main");
        assert_eq!(percent_decode("%22fn%20main%22"), "\"fn main\"");
        assert_eq!(percent_decode("colo(u%7C)r"), "colo(u|)r");
    }

    #[test]
    fn partitioning_is_stable_and_in_range() {
        for content in ["hello", "world", ""] {
            let p = (fnv1a(content.as_bytes()) % SHARDS as u64) as usize;
            assert!(p < SHARDS);
            assert_eq!(p, (fnv1a(content.as_bytes()) % SHARDS as u64) as usize);
        }
    }
}

//! Spec 003 acceptance 2: sharding preserves results. Runs the real binary
//! against a real broker and asserts the merged fan-out result equals a
//! monolithic spec-001 index of the same tree. Self-skips (passes) when
//! KAFKA_BROKER is unset so CI needs no broker.

use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::Path;
use std::time::{Duration, Instant};

fn http_get(path: &str) -> Option<String> {
    let mut s = TcpStream::connect("127.0.0.1:7878").ok()?;
    s.set_read_timeout(Some(Duration::from_secs(10))).ok()?;
    write!(
        s,
        "GET {path} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"
    )
    .ok()?;
    let mut buf = String::new();
    s.read_to_string(&mut buf).ok()?;
    buf.split_once("\r\n\r\n").map(|(_, body)| body.to_string())
}

fn monolithic_paths(root: &Path, q: &str) -> Vec<String> {
    let (docs, _) = mini_bb::ingest::ingest(root.to_str().unwrap()).unwrap();
    let idx = mini_bb::index::build("truth".into(), docs);
    let plans = mini_bb::query::plan(&mini_bb::query::parse(q));
    let cand = mini_bb::search::candidates(&idx, &plans);
    let mut paths: Vec<String> = mini_bb::search::verify(&idx, &plans, &cand)
        .iter()
        .flat_map(|m| m.doc.paths.iter().cloned())
        .collect();
    paths.sort();
    paths
}

#[test]
fn distributed_search_equals_monolithic() {
    if std::env::var("KAFKA_BROKER").is_err() {
        eprintln!("KAFKA_BROKER unset — skipping broker-dependent test");
        return;
    }
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .to_path_buf();
    let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_kafka-demo"))
        .current_dir(&root)
        .spawn()
        .expect("spawn kafka-demo");

    // Wait for the HTTP surface, trigger a push, then poll until the
    // eventually-consistent shards agree with the monolithic truth.
    let deadline = Instant::now() + Duration::from_secs(60);
    while http_get("/push").is_none() {
        assert!(Instant::now() < deadline, "demo never came up");
        std::thread::sleep(Duration::from_millis(500));
    }
    for q in ["fn+main", "arguments%3F"] {
        let plain = q.replace('+', " ").replace("%3F", "?");
        let want = monolithic_paths(&root, &plain);
        let got = loop {
            let body = http_get(&format!("/search?q={q}")).unwrap_or_default();
            let v: serde_json::Value = serde_json::from_str(&body).unwrap_or_default();
            let mut got: Vec<String> = v["merged"]
                .as_array()
                .map(|a| {
                    a.iter()
                        .filter_map(|p| p.as_str().map(String::from))
                        .collect()
                })
                .unwrap_or_default();
            got.sort();
            if got == want || Instant::now() > deadline {
                break got;
            }
            std::thread::sleep(Duration::from_secs(1));
        };
        assert_eq!(got, want, "distributed result diverged for {plain:?}");
        assert!(!want.is_empty(), "sanity: {plain:?} should match something");
    }
    let _ = child.kill();
    let _ = child.wait(); // reap — a killed child still needs wait()ing
}

// mini-bb web frontend (spec 001 WEB-1..WEB-4).
// This file MIRRORS the Rust engine — src/index.rs, src/query.rs,
// src/search.rs are the reference implementation. Keep the algorithms in
// lockstep: same trigram definition, same plan, same verify semantics.

"use strict";

let INDEX = null; // the loaded/built index, same JSON shape as FR-5

const $ = (id) => document.getElementById(id);
const status = (msg, isError = false) => {
  $("status").textContent = msg;
  $("status").classList.toggle("error", isError);
};

// ---------------------------------------------------------------- engine --
// Mirror of index.rs::trigrams — every window of 3 chars, case-folded.
// Array.from splits by code point (like Rust chars()), not UTF-16 units.
function trigrams(text) {
  const chars = Array.from(text.toLowerCase());
  const out = [];
  for (let i = 0; i + 3 <= chars.length; i++) {
    out.push(chars[i] + chars[i + 1] + chars[i + 2]);
  }
  return out;
}

// Mirror of query.rs::parse — bare words + "quoted strings", folded.
// Quoted terms stay fully literal; bare terms get the regex subset.
function parseQuery(query) {
  const terms = [];
  let cur = "";
  let inQuotes = false;
  const flush = (quoted) => {
    if (cur) terms.push({ raw: cur.toLowerCase(), quoted });
    cur = "";
  };
  for (const c of query) {
    if (c === '"') { flush(inQuotes); inQuotes = !inQuotes; }
    else if (/\s/.test(c) && !inQuotes) flush(false);
    else cur += c;
  }
  flush(inQuotes);
  return terms;
}

// Mirror of query.rs::expand — the regex subset: `?` (previous char
// optional), `(a|b)` alternation, `\` escape → all literal variants.
function expand(raw) {
  let out = [""];
  const chars = Array.from(raw);
  for (let i = 0; i < chars.length; i++) {
    const c = chars[i];
    if (c === "\\") { if (++i < chars.length) out = out.map((v) => v + chars[i]); }
    else if (c === "(") {
      let group = "";
      while (++i < chars.length && chars[i] !== ")") group += chars[i];
      out = out.flatMap((v) => group.split("|").map((b) => v + b));
    } else if (c === "?") {
      out = [...new Set([...out, ...out.map((v) => v.slice(0, -1))])].sort();
    } else out = out.map((v) => v + c);
  }
  return out;
}

// Mirror of query.rs::plan — terms AND, variants OR, trigrams AND.
function plan(terms) {
  return terms.map((t) => ({
    term: t.raw,
    variants: (t.quoted ? [t.raw] : expand(t.raw)).map((literal) => {
      const grams = trigrams(literal);
      return { literal, grams, scanAll: grams.length === 0 };
    }),
  }));
}

// Mirror of search.rs::candidates — AND over terms of term OR-sets.
function candidates(index, plans) {
  let acc = null;
  for (const p of plans) {
    const ids = termCandidates(index, p.variants);
    acc = acc === null ? ids : intersect(acc, ids);
  }
  return acc ?? [];
}

// Mirror of search.rs::term_candidates — union of variant intersections.
function termCandidates(index, variants) {
  let ids = [];
  for (const v of variants) {
    if (v.scanAll) return index.docs.map((d) => d.id);
    const lists = v.grams.map((g) => index.grams[g] ?? []);
    lists.sort((a, b) => a.length - b.length);
    let vIds = lists[0];
    for (const l of lists.slice(1)) {
      vIds = intersect(vIds, l);
      if (vIds.length === 0) break;
    }
    ids = union(ids, vIds);
  }
  return ids;
}

// Mirror of search.rs::intersect — two-pointer merge of sorted ID lists.
function intersect(a, b) {
  const out = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] < b[j]) i++;
    else if (a[i] > b[j]) j++;
    else { out.push(a[i]); i++; j++; }
  }
  return out;
}

// Mirror of search.rs::union — same walk, keeping everything once.
function union(a, b) {
  const out = [];
  let i = 0, j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] < b[j]) out.push(a[i++]);
    else if (a[i] > b[j]) out.push(b[j++]);
    else { out.push(a[i]); i++; j++; }
  }
  return out.concat(a.slice(i), b.slice(j));
}

// Mirror of search.rs::verify — trigram hits are candidates, not matches.
// A doc matches when every term has at least one variant literal present.
function verify(index, plans, ids) {
  const matches = [];
  for (const id of ids) {
    const doc = index.docs[id];
    const folded = doc.content.toLowerCase();
    if (!plans.every((p) => p.variants.some((v) => folded.includes(v.literal)))) continue;
    const lines = [];
    const foldedLines = folded.split("\n");
    const origLines = doc.content.split("\n");
    for (const p of plans) {
      for (let n = 0; n < foldedLines.length; n++) {
        const v = p.variants.find((v) => foldedLines[n].includes(v.literal));
        if (v) { lines.push({ term: v.literal, lineNo: n + 1, text: origLines[n] }); break; }
      }
    }
    matches.push({ doc, lines });
  }
  return matches;
}

// ------------------------------------------------------------- rendering --
const esc = (s) =>
  s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

function highlight(text, term) {
  const i = text.toLowerCase().indexOf(term);
  if (i < 0) return esc(text);
  return (
    esc(text.slice(0, i)) +
    "<mark>" + esc(text.slice(i, i + term.length)) + "</mark>" +
    esc(text.slice(i + term.length))
  );
}

function stage(title, bodyHtml) {
  return `<div class="stage"><h3>${title}</h3><div>${bodyHtml}</div></div>`;
}

// The FR-9 / WEB-4 pipeline: terms → expansion → plan → candidates → matches.
function runSearch() {
  if (!INDEX) return;
  const terms = parseQuery($("query").value);
  const el = $("stages");
  if (terms.length === 0) { el.innerHTML = ""; return; }
  const plans = plan(terms);

  let html = stage("terms (AND)", terms.map((t) => `<span class="chip term">${esc(t.raw)}</span>`).join(" "));

  html += stage("expand each term into variants (OR), each into covering trigrams",
    plans.map((p) =>
      `<div class="expansion"><span class="chip term">${esc(p.term)}</span> → ` +
      p.variants.map((v) =>
        `<span class="chip variant">${esc(v.literal) || "ε"}</span> ` +
        (v.scanAll
          ? `<span class="warn">shorter than a trigram — full scan of every doc!</span>`
          : v.grams.map((g) => `<span class="chip gram">${esc(g)}</span>`).join(" "))
      ).join(` <span class="dim">∨</span> `) +
      `</div>`).join(""));

  html += stage("plan — AND terms, OR variants, AND posting lists <span class='dim'>(chip badge = list length)</span>",
    plans.map((p) =>
      `<div class="expansion">` +
      p.variants.map((v) =>
        v.scanAll
          ? `<span class="warn">full scan</span>`
          : "( " + v.grams.map((g) => {
              const n = (INDEX.grams[g] ?? []).length;
              return `<span class="chip gram">${esc(g)}<b>${n}</b></span>`;
            }).join(" ∧ ") + " )"
      ).join(` <span class="dim">∨</span> `) +
      `</div>`).join(`<div class="dim">∧</div>`));

  const cand = candidates(INDEX, plans);
  html += stage("candidates after intersection",
    `<b>${cand.length}</b> of ${INDEX.docs.length} docs <span class="dim">— necessary, not sufficient: now verify</span>`);

  const matches = verify(INDEX, plans, cand);
  const removed = cand.length - matches.length;
  html += stage(`verified matches — ${matches.length} <span class="dim">(${removed} false positive${removed === 1 ? "" : "s"} removed)</span>`,
    matches.map((m) =>
      `<div class="match"><div class="paths">${m.doc.paths.map(esc).join(" = ")}</div>` +
      m.lines.map((l) => `<pre>${String(l.lineNo).padStart(4)}: ${highlight(l.text, l.term)}</pre>`).join("") +
      `</div>`).join("") || `<span class="dim">nothing matched</span>`);

  el.innerHTML = html;
}

// --------------------------------------------------------------- ingest --
// WEB-3: prebuilt demo index (this repo, generated by the Rust CLI).
async function loadDemo() {
  status("loading demo index…");
  try {
    const res = await fetch("demo/index.json");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    setIndex(await res.json(), "demo index");
  } catch (e) {
    status(`demo index failed to load: ${e.message}`, true);
  }
}

// WEB-2: in-browser ingest of a small public repo via the GitHub API.
// Mirrors FR-2 (text ≤ 100 KB here) and FR-3 (dedupe by content).
const MAX_FILES = 100;
const MAX_BYTES = 100 * 1024;

async function fetchRepo() {
  const m = $("repo-url").value.match(/^https:\/\/github\.com\/([^/]+)\/([^/]+?)(?:\.git|\/.*)?$/);
  if (!m) { status("enter a URL like https://github.com/owner/repo", true); return; }
  const [, owner, repo] = m;
  const headers = { Accept: "application/vnd.github+json" };
  const token = $("token").value.trim();
  if (token) headers.Authorization = `Bearer ${token}`;

  try {
    status("fetching file tree…");
    const treeRes = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/git/trees/HEAD?recursive=1`, { headers });
    if (!treeRes.ok) throw new Error(`tree fetch: HTTP ${treeRes.status} (rate limit? private repo?)`);
    const tree = await treeRes.json();

    const files = tree.tree
      .filter((e) => e.type === "blob" && e.size <= MAX_BYTES && !e.path.split("/").some((s) => s.startsWith(".")))
      .slice(0, MAX_FILES);
    if (files.length === 0) throw new Error("no indexable files found");

    // Dedupe by blob SHA — the same content-addressing trick as Blackbird
    // and FR-3, except GitHub already computed the hash for us.
    const bySha = new Map();
    const docs = [];
    let done = 0;
    for (const f of files) {
      status(`fetching blobs… ${++done}/${files.length}`);
      if (bySha.has(f.sha)) { docs[bySha.get(f.sha)].paths.push(f.path); continue; }
      const blobRes = await fetch(
        `https://api.github.com/repos/${owner}/${repo}/git/blobs/${f.sha}`,
        { headers: { ...headers, Accept: "application/vnd.github.raw+json" } });
      if (!blobRes.ok) throw new Error(`blob fetch: HTTP ${blobRes.status} (rate limit?)`);
      const content = await blobRes.text();
      if (content.includes("\0")) continue; // binary, mirror FR-2
      bySha.set(f.sha, docs.length);
      docs.push({ id: docs.length, paths: [f.path], hash: f.sha, content });
    }

    // Mirror of index.rs::build — one posting per doc per distinct gram;
    // ascending doc IDs keep the lists sorted for the merge-intersection.
    status("building trigram index…");
    const grams = {};
    for (const doc of docs) {
      for (const g of new Set(trigrams(doc.content))) (grams[g] ??= []).push(doc.id);
    }
    setIndex(
      { version: 1, source: `https://github.com/${owner}/${repo}`, docs, grams },
      `${owner}/${repo}`);
  } catch (e) {
    status(e.message, true);
  }
}

function setIndex(index, label) {
  INDEX = index;
  const grams = Object.keys(index.grams).length;
  status(`indexed ${label}: ${index.docs.length} docs, ${grams} distinct trigrams — search away`);
  $("search-panel").hidden = false;
  // WEB-6 (spec 002): the explorer is a separate, view-only module.
  if (window.renderExplorer) window.renderExplorer(index);
  $("query").focus();
  runSearch();
}

// ------------------------------------------------------------------ wire --
$("demo-btn").addEventListener("click", loadDemo);
$("fetch-btn").addEventListener("click", fetchRepo);
$("search-btn").addEventListener("click", runSearch);
$("query").addEventListener("input", runSearch);
$("repo-url").addEventListener("keydown", (e) => { if (e.key === "Enter") fetchRepo(); });

