// Index explorer (spec 002, WEB-6..WEB-8): two read-only views over the
// FR-5 index JSON — a file-browser view of the deduplicated doc store, and
// an inverted-index view (D3 charts + gram lookup). This module is NOT part
// of the Rust↔JS mirror; it only *reads* the index shape.
// Exposes exactly one global: window.renderExplorer(index).

"use strict";

(() => {
  const $ = (id) => document.getElementById(id);
  const escx = (s) =>
    String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  // Grams can contain whitespace; make it visible in labels.
  const visGram = (g) => g.replaceAll(" ", "·").replaceAll("\n", "⏎").replaceAll("\t", "⇥");
  const showGram = (g) => escx(visGram(g)); // HTML-safe variant

  let IDX = null;
  let gramCountPerDoc = [];

  // ------------------------------------------------------------- files --
  // Build a nested directory tree from every path of every doc (WEB-7).
  function buildTree(docs) {
    const root = { dirs: new Map(), files: [] };
    for (const doc of docs) {
      for (const path of doc.paths) {
        const parts = path.split("/");
        let node = root;
        for (const part of parts.slice(0, -1)) {
          if (!node.dirs.has(part)) node.dirs.set(part, { dirs: new Map(), files: [] });
          node = node.dirs.get(part);
        }
        node.files.push({ name: parts[parts.length - 1], path, doc });
      }
    }
    return root;
  }

  function countFiles(node) {
    let n = node.files.length;
    for (const d of node.dirs.values()) n += countFiles(d);
    return n;
  }

  function fileAttrs(f) {
    const { doc } = f;
    const bytes = new TextEncoder().encode(doc.content).length;
    const lines = doc.content.split("\n").length;
    const dups = doc.paths.filter((p) => p !== f.path);
    return `<table class="attrs">
      <tr><th>doc id</th><td>${doc.id}</td></tr>
      <tr><th>content hash</th><td><code>${escx(doc.hash)}</code></td></tr>
      <tr><th>size</th><td>${bytes.toLocaleString()} bytes · ${lines.toLocaleString()} lines</td></tr>
      <tr><th>distinct trigrams</th><td>${(gramCountPerDoc[doc.id] ?? 0).toLocaleString()}</td></tr>
      ${dups.length
        ? `<tr><th>deduped with</th><td>${dups.map((p) => `<code>${escx(p)}</code>`).join("<br>")}
           <span class="dim">(identical content — indexed once, FR-3)</span></td></tr>`
        : ""}
    </table>`;
  }

  function renderNode(node) {
    let html = "";
    for (const name of [...node.dirs.keys()].sort()) {
      const dir = node.dirs.get(name);
      const n = countFiles(dir);
      html += `<details class="tree dir"><summary>${escx(name)}/
        <span class="dim">${n} file${n === 1 ? "" : "s"}</span></summary>${renderNode(dir)}</details>`;
    }
    for (const f of [...node.files].sort((a, b) => a.name.localeCompare(b.name))) {
      const dup = f.doc.paths.length > 1 ? ` <span class="dup" title="content shared with another path">=</span>` : "";
      html += `<details class="tree file"><summary>${escx(f.name)}${dup}
        <span class="dim">doc ${f.doc.id}</span></summary>${fileAttrs(f)}</details>`;
    }
    return html;
  }

  // ------------------------------------------------------------- charts --
  const BAR = "var(--chart-bar)"; // validated for both themes (spec 002)

  function tooltip(html, event) {
    const t = $("exp-tooltip");
    if (!html) { t.hidden = true; return; }
    t.innerHTML = html;
    t.hidden = false;
    const pad = 12;
    const w = t.offsetWidth;
    const x = Math.min(event.pageX + pad, document.documentElement.clientWidth - w - pad);
    t.style.left = `${Math.max(pad, x)}px`;
    t.style.top = `${event.pageY + pad}px`;
  }

  // Histogram of posting-list sizes (WEB-8): x = docs per gram, y = grams.
  function renderHist(lens) {
    const el = $("exp-hist");
    el.innerHTML = "";
    const width = Math.max(el.clientWidth || 320, 280);
    const height = 180;
    const m = { top: 8, right: 12, bottom: 34, left: 56 };
    const bins = d3.bin().domain([1, d3.max(lens) + 1]).thresholds(Math.min(24, d3.max(lens)))(lens);
    const x = d3.scaleLinear().domain([1, d3.max(lens) + 1]).range([m.left, width - m.right]);
    const y = d3.scaleLinear().domain([0, d3.max(bins, (b) => b.length)]).nice()
      .range([height - m.bottom, m.top]);

    const svg = d3.select(el).append("svg").attr("width", width).attr("height", height);
    svg.append("g").attr("class", "axis")
      .attr("transform", `translate(0,${height - m.bottom})`)
      .call(d3.axisBottom(x).ticks(6).tickSizeOuter(0));
    svg.append("g").attr("class", "axis")
      .attr("transform", `translate(${m.left},0)`)
      .call(d3.axisLeft(y).ticks(4).tickSizeOuter(0));
    svg.append("text").attr("class", "axis-label")
      .attr("x", (m.left + width - m.right) / 2).attr("y", height - 4)
      .text("posting-list length (docs containing the gram)");
    svg.append("text").attr("class", "axis-label")
      .attr("transform", `translate(11,${(m.top + height - m.bottom) / 2}) rotate(-90)`)
      .text("grams");

    svg.append("g").selectAll("rect").data(bins).join("rect")
      .attr("x", (b) => x(b.x0) + 1)
      .attr("width", (b) => Math.max(1, x(b.x1) - x(b.x0) - 2))
      .attr("y", (b) => y(b.length))
      .attr("height", (b) => y(0) - y(b.length))
      .attr("rx", 2)
      .style("fill", BAR)
      .on("mousemove", (ev, b) => tooltip(
        `<b>${b.length.toLocaleString()}</b> grams appear in ${b.x0}–${b.x1 - 1} docs`, ev))
      .on("mouseleave", () => tooltip(null));
  }

  // Top-N grams by posting-list length (WEB-8), horizontal bars.
  function renderTop(entries) {
    const el = $("exp-top");
    el.innerHTML = "";
    const top = entries.slice(0, 30);
    const width = Math.max(el.clientWidth || 320, 280);
    const rowH = 18;
    const m = { top: 4, right: 46, bottom: 4, left: 52 };
    const height = m.top + m.bottom + top.length * rowH;
    const x = d3.scaleLinear().domain([0, top[0][1].length]).range([0, width - m.left - m.right]);

    const svg = d3.select(el).append("svg").attr("width", width).attr("height", height);
    const row = svg.append("g").selectAll("g").data(top).join("g")
      .attr("transform", (_, i) => `translate(${m.left},${m.top + i * rowH})`)
      .attr("class", "gram-row")
      .style("cursor", "pointer")
      .on("mousemove", (ev, [g, list]) => tooltip(
        `<code>${showGram(g)}</code> appears in <b>${list.length}</b> of ${IDX.docs.length} docs — click for the posting list`, ev))
      .on("mouseleave", () => tooltip(null))
      .on("click", (_, [g]) => showPostings(g));
    row.append("text").attr("class", "gram-label")
      .attr("x", -6).attr("y", rowH / 2).attr("dy", "0.35em").attr("text-anchor", "end")
      .text(([g]) => visGram(g));
    row.append("rect")
      .attr("y", 2).attr("height", rowH - 4).attr("rx", 2)
      .attr("width", ([, list]) => Math.max(1, x(list.length)))
      .style("fill", BAR);
    row.append("text").attr("class", "bar-value")
      .attr("x", ([, list]) => x(list.length) + 5).attr("y", rowH / 2).attr("dy", "0.35em")
      .text(([, list]) => list.length);
  }

  // ------------------------------------------------------ gram lookup --
  function showPostings(gram) {
    const list = IDX.grams[gram] ?? [];
    $("gram-detail").innerHTML =
      `<h3>posting list for <span class="chip gram">${showGram(gram)}</span> — ${list.length} docs</h3>` +
      list.map((id) => `<span class="chip path">${escx(IDX.docs[id].paths.join(" = "))}</span>`).join(" ");
    $("gram-detail").scrollIntoView({ block: "nearest", behavior: "smooth" });
  }

  function renderFilter() {
    const q = $("gram-filter").value.toLowerCase();
    const el = $("gram-list");
    if (!q) { el.innerHTML = ""; return; }
    const hits = Object.entries(IDX.grams).filter(([g]) => g.includes(q)).slice(0, 60);
    el.innerHTML = hits.length
      ? hits.map(([g, list]) =>
          `<button class="chip gram clickable" data-gram="${escx(g)}">${showGram(g)}<b>${list.length}</b></button>`).join(" ")
      : `<span class="dim">no grams match</span>`;
    for (const b of el.querySelectorAll("[data-gram]")) {
      b.addEventListener("click", () => showPostings(b.dataset.gram));
    }
  }

  // -------------------------------------------------------------- wire --
  function renderGrams() {
    const entries = Object.entries(IDX.grams).sort((a, b) => b[1].length - a[1].length);
    const lens = entries.map(([, list]) => list.length);
    const total = d3.sum(lens);
    $("gram-stats").textContent =
      `${entries.length.toLocaleString()} distinct trigrams · ${total.toLocaleString()} postings · ` +
      `average list ${(total / entries.length).toFixed(1)} docs · longest ${lens[0]} of ${IDX.docs.length} docs`;
    renderHist(lens);
    renderTop(entries);
  }

  window.renderExplorer = (index) => {
    IDX = index;
    // Distinct-trigram count per doc, derived from the inverted index itself.
    gramCountPerDoc = new Array(index.docs.length).fill(0);
    for (const list of Object.values(index.grams)) for (const id of list) gramCountPerDoc[id]++;
    $("view-files").innerHTML = renderNode(buildTree(index.docs));
    $("gram-detail").innerHTML = "";
    $("gram-list").innerHTML = "";
    $("gram-filter").value = "";
    if (!$("view-grams").hidden) renderGrams();
    $("explore-panel").hidden = false;
  };

  function selectTab(which) {
    $("view-files").hidden = which !== "files";
    $("view-grams").hidden = which !== "grams";
    $("tab-files").classList.toggle("active", which === "files");
    $("tab-grams").classList.toggle("active", which === "grams");
    if (which === "grams" && IDX) renderGrams(); // charts need visible widths
  }
  $("tab-files").addEventListener("click", () => selectTab("files"));
  $("tab-grams").addEventListener("click", () => selectTab("grams"));
  $("gram-filter").addEventListener("input", renderFilter);
  let resizeTimer;
  window.addEventListener("resize", () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => { if (IDX && !$("view-grams").hidden) renderGrams(); }, 150);
  });
})();

// Kafka pipeline visualization (spec 003, WEB-10/WEB-11): animates real
// recorded (or live) pipeline events — push → crawler → docs topic
// partitions → shards, and the query fan-out that deliberately bypasses
// Kafka. Data sources: web/demo/kafka-events.jsonl (replay, recorded from a
// real broker run) or a local kafka-demo at http://localhost:7878 (live).
// View-only; exposes no globals.

"use strict";

(() => {
  const $ = (id) => document.getElementById(id);
  const esc = (s) =>
    String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const LIVE_URL = "http://localhost:7878";
  const INGEST = "var(--chart-bar)"; // async path (validated, both themes)
  const QUERY = "var(--chart-query)"; // sync path (validated, both themes)

  // ---------------------------------------------------------- the diagram --
  // Fixed layout in a 760×330 viewBox; nodes are (x, y, w, h).
  const N = {
    push: [10, 40, 96, 36, "push event"],
    crawler: [160, 40, 96, 36, "crawler"],
    p0: [310, 16, 130, 40, "docs · p0"],
    p1: [310, 72, 130, 40, "docs · p1"],
    p2: [310, 128, 130, 40, "docs · p2"],
    s0: [520, 10, 228, 52, "shard 0"],
    s1: [520, 66, 228, 52, "shard 1"],
    s2: [520, 122, 228, 52, "shard 2"],
    query: [10, 250, 96, 36, "query"],
    merge: [310, 250, 130, 40, "merge"],
  };
  const mid = (k) => [N[k][0] + N[k][2] / 2, N[k][1] + N[k][3] / 2];
  const right = (k) => [N[k][0] + N[k][2], N[k][1] + N[k][3] / 2];
  const left = (k) => [N[k][0], N[k][1] + N[k][3] / 2];

  let svg;
  function initDiagram() {
    svg = d3
      .select("#pipe-diagram")
      .append("svg")
      .attr("viewBox", "0 0 760 330")
      .attr("preserveAspectRatio", "xMidYMid meet");
    const edges = [
      ["push", "crawler", INGEST, ""],
      ["crawler", "p0", INGEST, ""], ["crawler", "p1", INGEST, ""], ["crawler", "p2", INGEST, ""],
      ["p0", "s0", INGEST, ""], ["p1", "s1", INGEST, ""], ["p2", "s2", INGEST, ""],
      ["query", "s0", QUERY, "4 3"], ["query", "s1", QUERY, "4 3"], ["query", "s2", QUERY, "4 3"],
      ["s0", "merge", QUERY, "4 3"], ["s1", "merge", QUERY, "4 3"], ["s2", "merge", QUERY, "4 3"],
    ];
    for (const [a, b, , dash] of edges) {
      const [x1, y1] = right(a);
      const [x2, y2] = left(b);
      svg.append("line").attr("class", "pipe-edge").attr("stroke-dasharray", dash)
        .attr("x1", x1).attr("y1", y1).attr("x2", x2).attr("y2", y2);
    }
    for (const [key, [x, y, w, h, label]] of Object.entries(N)) {
      const g = svg.append("g");
      g.append("rect").attr("class", `pipe-node ${/^s\d/.test(key) ? "pipe-shard" : ""}`)
        .attr("x", x).attr("y", y).attr("width", w).attr("height", h).attr("rx", 8);
      g.append("text").attr("class", "pipe-label").attr("x", x + 10).attr("y", y + 16).text(label);
      g.append("text").attr("class", "pipe-meta").attr("id", `pipe-meta-${key}`)
        .attr("x", x + 10).attr("y", y + (h > 40 ? 34 : 30)).text("");
    }
    // The lesson, written on the diagram itself.
    svg.append("text").attr("class", "pipe-meta").attr("x", 10).attr("y", 205)
      .text("solid = async ingest (real Kafka messages)");
    svg.append("text").attr("class", "pipe-meta").attr("x", 10).attr("y", 222)
      .text("dashed = sync query fan-out (no Kafka)");
  }

  const meta = (key, text) => svg.select(`#pipe-meta-${key}`).text(text);

  function dot(a, b, color, dur = 550) {
    const [x1, y1] = right(a);
    const [x2, y2] = left(b);
    svg.append("circle").attr("class", "pipe-dot").attr("r", 5).style("fill", color)
      .attr("cx", x1).attr("cy", y1)
      .transition().duration(dur).ease(d3.easeQuadInOut)
      .attr("cx", x2).attr("cy", y2)
      .remove();
  }

  // --------------------------------------------------------- event router --
  const partCount = [0, 0, 0];
  function handle(ev) {
    switch (ev.ev) {
      case "push":
        dot("push", "crawler", INGEST);
        break;
      case "crawl":
        meta("crawler", `${ev.docs} docs (${ev.merged} deduped)`);
        break;
      case "produce":
        partCount[ev.partition]++;
        dot("crawler", `p${ev.partition}`, INGEST);
        meta(`p${ev.partition}`, `${partCount[ev.partition]} msgs`);
        break;
      case "indexed":
        dot(`p${ev.shard}`, `s${ev.shard}`, INGEST);
        meta(`s${ev.shard}`, `${ev.docs} docs · ${ev.grams.toLocaleString()} trigrams`);
        break;
      case "fanout":
        meta("query", `“${ev.q}”`);
        meta("merge", "");
        for (const s of ["s0", "s1", "s2"]) dot("query", s, QUERY);
        break;
      case "shard_result":
        dot(`s${ev.shard}`, "merge", QUERY);
        break;
      case "merged":
        meta("merge", `${ev.total} results`);
        $("pipe-log").innerHTML =
          `<span class="chip term">${esc(ev.q)}</span> → <b>${ev.total}</b> merged results` +
          `<span class="dim"> — fan-out answered by all shards</span>`;
        break;
    }
  }

  // -------------------------------------------------------------- replay --
  let replayTimers = [];
  async function replay() {
    stopLive();
    replayTimers.forEach(clearTimeout);
    replayTimers = [];
    partCount.fill(0);
    ["crawler", "p0", "p1", "p2", "s0", "s1", "s2", "query", "merge"].forEach((k) => meta(k, ""));
    $("pipe-status").textContent = "replaying a recorded run against a real broker…";
    let lines;
    try {
      const res = await fetch("demo/kafka-events.jsonl");
      lines = (await res.text()).trim().split("\n").map((l) => JSON.parse(l));
    } catch {
      $("pipe-status").textContent = "could not load the recorded run";
      return;
    }
    // Real timestamps, but gaps compressed to keep the story watchable:
    // ≥120 ms between events, ≤900 ms per gap.
    let t = 300;
    lines.forEach((ev, i) => {
      const dt = i ? Math.min(900, Math.max(120, ev.ts - lines[i - 1].ts)) : 0;
      t += dt;
      replayTimers.push(setTimeout(() => handle(ev), t));
    });
    replayTimers.push(setTimeout(() => {
      $("pipe-status").textContent = "replay finished — every dot was a real Kafka message (or fan-out call)";
    }, t + 700));
  }

  // ---------------------------------------------------------------- live --
  let es = null;
  function stopLive() {
    if (es) es.close();
    es = null;
    $("pipe-live-controls").hidden = true;
  }
  function connectLive() {
    replayTimers.forEach(clearTimeout);
    stopLive();
    $("pipe-status").textContent = `connecting to ${LIVE_URL}…`;
    es = new EventSource(`${LIVE_URL}/events`);
    es.onopen = () => {
      $("pipe-status").textContent = "live — connected to the local kafka-demo";
      $("pipe-live-controls").hidden = false;
    };
    es.onmessage = (m) => handle(JSON.parse(m.data));
    es.onerror = () => {
      $("pipe-status").textContent =
        "no local demo found — run: docker compose -f kafka-demo/docker-compose.yml up -d && cargo run -p kafka-demo";
      stopLive();
    };
  }
  async function livePush() {
    try { await fetch(`${LIVE_URL}/push`); } catch { /* surfaced via SSE silence */ }
  }
  async function liveSearch() {
    const q = $("pipe-query").value.trim();
    if (!q) return;
    try {
      const res = await fetch(`${LIVE_URL}/search?q=${encodeURIComponent(q)}`);
      const r = await res.json();
      $("pipe-log").innerHTML =
        `<span class="chip term">${esc(r.q)}</span> → <b>${r.merged.length}</b> merged results<br>` +
        r.merged.map((p) => `<span class="chip path">${esc(p)}</span>`).join(" ");
    } catch {
      $("pipe-log").textContent = "search failed — is the local demo running?";
    }
  }

  // ---------------------------------------------------------------- wire --
  initDiagram();
  $("pipe-replay").addEventListener("click", replay);
  $("pipe-live").addEventListener("click", connectLive);
  $("pipe-push").addEventListener("click", livePush);
  $("pipe-search").addEventListener("click", liveSearch);
  $("pipe-query").addEventListener("keydown", (e) => { if (e.key === "Enter") liveSearch(); });
  replay(); // auto-play the recorded run on page load
})();

